/**
 * Returns the values to dump on serialize() called on.
 *
 * The local translator (that may contain closures) is not dumped, it's
 * restored from the dumped locale on unserialize().
 *
 * @return array
 */
public function __serialize(): array
{
    $data = get_object_vars($this);

    if (isset($data['step']) && $data['step'] instanceof Closure) {
        $data['step'] = null;
    }

    unset($data['localTranslator'], $data['from_string'], $data['days']);
    $data['dumpLocale'] = isset($this->localTranslator)
        ? $this->getTranslatorLocale($this->localTranslator)
        : null;

    return $data;
}

/**
 * Restore the instance on unserialize() called on.
 *
 * @param array $data data as dumped by __serialize()
 */
public function __unserialize(array $data): void
{
    // Initialize the native DateInterval internal state so unit
    // properties can be set without passing through __set().
    $this->__construct(0);

    $dumpLocale = $data['dumpLocale'] ?? null;
    unset($data['dumpLocale']);

    // Handle Carbon 2 serialized intervals where the timezone
    // was dumped using the `tzName` property name.
    if (isset($data['tzName'])) {
        $data['timezoneSetting'] = $data['tzName'];
        unset($data['tzName']);
    }

    // Writing to the read-only `days` property would reset the
    // whole native DateInterval internal state.
    unset($data['from_string'], $data['days']);

    foreach ($data as $key => $value) {
        $this->$key = $value;
    }

    if ($dumpLocale) {
        $this->localTranslator = Translator::get($dumpLocale);
    }
}

/**
 * Return the current context from inside a macro callee or a new one if static.
 *
 * @return static
 */
protected static function this(): static
{
    return end(static::$macroContextStack) ?: new static(0);
}

